// Avoid invalidating HUD styles when their rendered value has not changed.
const aimOverlayStyles = new WeakMap();
function writeAimOverlayStyle(element, key, value) {
  let previous = aimOverlayStyles.get(element);
  if (!previous) aimOverlayStyles.set(element, previous = {});
  if (previous[key] === value) return;
  previous[key] = value;
  if (key.startsWith('--')) {
    element.style.setProperty(key, value);
  } else element.style[key] = value;
}
function toggleAimOverlayClass(element, name, enabled) {
  if (element.classList.contains(name) !== enabled) element.classList.toggle(name, enabled);
}
